(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d', { alpha: false });
  const mapCanvas = document.getElementById('minimap'), mapCtx = mapCanvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const mix = (a,b,t) => a+(b-a)*t;
  const SAVE_KEY = 'city-of-shadows-afterlight-v1';
  const missions = [
    {title:'A CITY THAT FORGETS', copy:'Find Mara at the Lantern Café. The old port holds more than cargo.', objective:'REACH THE LANTERN CAFÉ', reward:350, place:[38,24], district:'OLD HARBOR', complete:'A NEW LEAD', result:'Mara has a name: Elias Venn. Last seen near the floodlit freight yard.'},
    {title:'THE NIGHT LEDGER', copy:'Mara needs a ledger from a parked courier car. Find it before the harbor shift changes.', objective:'FIND THE COURIER CAR', reward:500, place:[-65,83], district:'FREIGHT QUARTER', complete:'PAPER TRAIL', result:'One account keeps appearing: Northline Development.'},
    {title:'A FAVOR IN GLASS', copy:'Meet fixer Tomas on the avenue. He knows which doors Northline keeps locked.', objective:'MEET TOMAS ON THE AVENUE', reward:650, place:[115,-54], district:'GLASS AVENUE', complete:'THE CITY HAS TEETH', result:'Northline has been buying the shoreline one deed at a time.'},
    {title:'AFTER THE RAIN', copy:'Take the signed photograph to Mara. This is only the first chapter.', objective:'RETURN TO MARA', reward:900, place:[38,24], district:'OLD HARBOR', complete:'CHAPTER ONE · AFTERLIGHT', result:'A new life takes shape. The rest of the city is yours to discover.'}
  ];
  let saved = {}; try { saved = JSON.parse(localStorage.getItem(SAVE_KEY) || '{}'); } catch {}
  const player = {x:saved.x||0,z:saved.z||0,yaw:saved.yaw||0, health:100,money:saved.money??1250, mission:clamp(saved.mission||0,0,missions.length-1), inCar:false, speed:0, run:false, crouch:false, interior:false};
  const settings = {quality:Number(localStorage.getItem('cos-quality')||1), sound:localStorage.getItem('cos-sound')!=='off'};
  let W=innerWidth,H=innerHeight,DPR=1, focal=700, paused=false, elapsed=0, time=18.7, weather='CLEAR', toastTimer=0, last=performance.now(), frameCount=0, fpsTimer=0, fps=30;
  let camYaw=0, camX=0, camZ=0, cameraY=8, cameraPitch=.29;
  const keys = new Set(), touch = {forward:0,side:0};
  const colors=['#27353a','#334044','#3c4548','#3a4143','#2c393c','#48504e','#2c3437','#40474a','#29383d'];
  const buildings=[];
  for(let gx=-6;gx<=6;gx++) for(let gz=-6;gz<=6;gz++) {
    if(Math.abs(gx)>5||Math.abs(gz)>5) continue;
    for(let n=0;n<3;n++){
      const seed=Math.abs(Math.sin(gx*127.1+gz*311.7+n*74.7)*43758.5453)%1;
      const seed2=Math.abs(Math.sin(gx*269.5+gz*183.3+n*39.4)*24634.6345)%1;
      let x=gx*60+(n===0?-17: n===1?17:0)+(seed-.5)*8;
      let z=gz*60+(n===2?-18: n===1?17:-17)+(seed2-.5)*8;
      const downtown=Math.max(0,1-Math.hypot(gx-1,gz+1)/4.3);
      let w=16+seed*15,d=17+seed2*15,h=12+seed*30+downtown*(20+seed2*42);
      if(Math.abs(gx)<1&&Math.abs(gz)<1) h=8+seed*12;
      buildings.push({x,z,w,d,h,color:colors[Math.floor(seed*colors.length)],lit:seed2, style:n,seed});
    }
  }
  const traffic=[];
  for(let i=0;i<18;i++) traffic.push({x:(i%6-2.5)*60+(i%2?7:-7),z:(Math.floor(i/6)-1)*60+(i%2? -20:20),dir:i%2?1:-1,axis:i%3===0?'x':'z',speed:5+(i%5)*1.25,color:['#b8b2a1','#9d4b37','#344951','#c0a76e','#536058'][i%5],phase:i*3.1});
  const walkers=[];
  for(let i=0;i<26;i++)walkers.push({x:(i%6-2.5)*60+(i%2?11:-11),z:(Math.floor(i/6)-2)*60+(i%3?16:-16),angle:(i*2.39),speed:.45+(i%4)*.12,phase:i*1.7});
  const missionsData=missions;
  function store(){try{localStorage.setItem(SAVE_KEY,JSON.stringify({x:player.x,z:player.z,yaw:player.yaw,money:player.money,mission:player.mission}));}catch{}}
  function resize(){DPR=Math.min(devicePixelRatio||1,1.7);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);focal=Math.min(W,H)*.93;}
  addEventListener('resize',resize,{passive:true});resize();
  function proj(x,y,z){
    const dx=x-camX,dz=z-camZ, right=dx*Math.cos(camYaw)-dz*Math.sin(camYaw), depth=dx*Math.sin(camYaw)+dz*Math.cos(camYaw);
    const vy=(y-cameraY)*Math.cos(cameraPitch)-depth*Math.sin(cameraPitch), dep=(y-cameraY)*Math.sin(cameraPitch)+depth*Math.cos(cameraPitch);
    if(dep<1.6)return null;
    return {x:W*.5+right*focal/dep,y:H*.47-vy*focal/dep,d:dep};
  }
  function poly(points,fill,stroke=null){const p=points.map(v=>proj(v[0],v[1],v[2]));if(p.some(v=>!v))return;ctx.beginPath();ctx.moveTo(p[0].x,p[0].y);for(let i=1;i<p.length;i++)ctx.lineTo(p[i].x,p[i].y);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.7;ctx.stroke();}}
  function box(x,z,w,d,h,base,opts={}){
    const x0=x-w/2,x1=x+w/2,z0=z-d/2,z1=z+d/2,y0=opts.y||0,y1=y0+h;
    const cc=opts.colors||[base,shade(base,-13),shade(base,12),shade(base,-21)];
    // Faces, sorted by camera-facing depth, with subtle material variation.
    const faces=[{q:[[x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0]],c:cc[1],center:(x0+x1)/2*Math.sin(camYaw)+(z0)*Math.cos(camYaw)},
      {q:[[x1,y0,z1],[x0,y0,z1],[x0,y1,z1],[x1,y1,z1]],c:cc[2],center:(x1+x0)/2*Math.sin(camYaw)+z1*Math.cos(camYaw)},
      {q:[[x0,y0,z1],[x0,y0,z0],[x0,y1,z0],[x0,y1,z1]],c:cc[0],center:x0*Math.sin(camYaw)+(z0+z1)/2*Math.cos(camYaw)},
      {q:[[x1,y0,z0],[x1,y0,z1],[x1,y1,z1],[x1,y1,z0]],c:cc[3],center:x1*Math.sin(camYaw)+(z0+z1)/2*Math.cos(camYaw)},
      {q:[[x0,y1,z0],[x1,y1,z0],[x1,y1,z1],[x0,y1,z1]],c:cc[0],center:(x0+x1)/2*Math.sin(camYaw)+(z0+z1)/2*Math.cos(camYaw)}];
    faces.sort((a,b)=>a.center-b.center);
    for(const f of faces){poly(f.q,f.c);if(f.q.length&&opts.windows&&f.center>0) facadeWindows(f.q,x,z,w,d,h,opts.seed||.5,f.c);}
  }
  function facadeWindows(face,x,z,w,d,h,seed,base){
    // Recede the little window marks into the building face, giving the city a lived-in rhythm.
    if(h<14||W<450)return;
    const topY=Math.max(5,h*.78), rows=Math.min(8,Math.floor(topY/4)), cols=Math.min(6,Math.floor(Math.max(w,d)/5));
    const front=face[0][2]===face[1][2], frontZ=face[0][2], frontX=face[0][0];
    for(let r=1;r<rows;r++)for(let c=0;c<cols;c++){
      const u=(c+1)/(cols+1), yy=2.2+r*(topY-2)/rows;
      let xx=front?x-w/2+u*w:frontX;
      let zz=front?frontZ:z-d/2+u*d;
      const p1=proj(xx-.65,yy,zz),p2=proj(xx+.65,yy,zz),p3=proj(xx+.65,yy+1.15,zz),p4=proj(xx-.65,yy+1.15,zz);
      if([p1,p2,p3,p4].some(p=>!p))continue;
      ctx.fillStyle=((Math.floor(x+z+c*3+r*5+seed*10)%9)===0)?'#e4bd76aa':'#a9c1c122';ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.lineTo(p3.x,p3.y);ctx.lineTo(p4.x,p4.y);ctx.closePath();ctx.fill();
    }
  }
  function shade(hex,amount){const n=parseInt(hex.slice(1),16),r=clamp((n>>16)+amount,0,255),g=clamp(((n>>8)&255)+amount,0,255),b=clamp((n&255)+amount,0,255);return '#'+((1<<24)+(r<<16)+(g<<8)+b).toString(16).slice(1);}
  function groundRect(x,z,w,d,color){poly([[x-w/2,0,z-d/2],[x+w/2,0,z-d/2],[x+w/2,0,z+d/2],[x-w/2,0,z+d/2]],color);}
  function drawWorld(){
    let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,time<6||time>20?'#111c27':'#31464b');sky.addColorStop(.52,time<6||time>20?'#586568':'#89958c');sky.addColorStop(1,'#69716a');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    const horizon=H*.48;let haze=ctx.createLinearGradient(0,horizon-30,0,horizon+150);haze.addColorStop(0,'#c7bd9b00');haze.addColorStop(.55,'#c7bd9b52');haze.addColorStop(1,'#666e6555');ctx.fillStyle=haze;ctx.fillRect(0,horizon-30,W,180);
    // Entire city ground plane and broad orthogonal asphalt grid.
    groundRect(0,0,790,790,'#3a4543');
    for(let i=-6;i<=6;i++){
      let c=(Math.abs(i)%3===0)?'#262f30':'#303a3a';
      groundRect(i*60,0,12,790,c);groundRect(0,i*60,790,12,c);
      // pale curb edge, subtle lane markings
      groundRect(i*60-7.5,0,1,790,'#77796c');groundRect(i*60+7.5,0,1,790,'#77796c');
      groundRect(i*60,0,.19,790,'#a49d83');groundRect(0,i*60,790,.19,'#a49d83');
      for(let j=-6;j<=6;j++)if(Math.abs(j)%2===0){groundRect(i*60, j*60+19, .23,8,'#b4aa8a');groundRect(j*60+19,i*60,8,.23,'#b4aa8a');}
    }
    // Building blocks as distant silhouettes and close detailed landmarks.
    const sorted=buildings.map(b=>({...b,depth:(b.x-camX)*Math.sin(camYaw)+(b.z-camZ)*Math.cos(camYaw)})).filter(b=>b.depth>-36&&b.depth<320).sort((a,b)=>b.depth-a.depth);
    for(const b of sorted){
      const dist=Math.hypot(b.x-player.x,b.z-player.z);if(dist>330)continue;
      const color=dist>210?'#374143':b.color;
      box(b.x,b.z,b.w,b.d,b.h,color,{windows:dist<190,seed:b.seed});
      if(b.h>37&&dist<210){box(b.x,b.z,b.w*.46,b.d*.48,2,'#69736d',{y:b.h});}
      if(dist<95&&b.seed>.58){groundRect(b.x,b.z,b.w*.67,b.d*.65,'#424b48');}
    }
    drawStreetDetails();
    for(const t of traffic)drawCar(t.x,t.z,t.axis==='x'?Math.PI/2:0,t.color,false);
    for(const p of walkers)drawPerson(p.x,p.z,p.angle,'#a7987a',false);
    drawMarker();
    if(player.inCar)drawCar(player.x,player.z,player.yaw,'#65766f',true);else drawPerson(player.x,player.z,player.yaw,'#c5b790',true);
    if(weather==='RAIN')drawRain();
  }
  function drawStreetDetails(){
    // Lamps, palms, curbside props, stop bars, parked cars, and crosswalks.
    const nearest=[];
    for(let x=-300;x<=300;x+=60)for(let z=-300;z<=300;z+=60)nearest.push([x,z]);
    nearest.sort((a,b)=>Math.hypot(a[0]-player.x,a[1]-player.z)-Math.hypot(b[0]-player.x,b[1]-player.z));
    for(const [x,z] of nearest.slice(0,30)){
      for(const side of [-1,1]){
        const lx=x+side*10.4,lz=z+17;
        let base=proj(lx,0,lz), top=proj(lx,6.2,lz);if(!base||!top||base.d>150)continue;
        ctx.strokeStyle='#282f2e';ctx.lineWidth=Math.max(1,4*focal/base.d);ctx.beginPath();ctx.moveTo(base.x,base.y);ctx.lineTo(top.x,top.y);ctx.stroke();
        ctx.fillStyle=time>19||time<6?'#f5d69c':'#d7c899';ctx.globalAlpha=time>19||time<6?.9:.28;ctx.beginPath();ctx.arc(top.x,top.y,Math.max(1,3*focal/base.d),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
      }
      if(Math.abs(x-player.x)<110&&Math.abs(z-player.z)<110){
        for(let i=0;i<4;i++){let zz=z+7+i*2.3;groundRect(x+10.2,zz,4,.85,'#c2baa0');}
        drawCar(x-9,z-14,0,'#4d5552',false,true);
      }
    }
  }
  function drawCar(x,z,yaw,color,hero=false,parked=false){
    const rot=(lx,lz)=>[x+lx*Math.cos(yaw)+lz*Math.sin(yaw),z-lx*Math.sin(yaw)+lz*Math.cos(yaw)];
    const len=hero?5.1:4.15,w=hero?2.45:1.9;
    const corners=[[-w/2,-len/2],[w/2,-len/2],[w/2,len/2],[-w/2,len/2]].map(a=>rot(a[0],a[1]));
    const q=corners.map(v=>proj(v[0],.85,v[1]));if(q.some(v=>!v)||q[0].d>190)return;
    ctx.beginPath();ctx.moveTo(q[0].x,q[0].y);for(let i=1;i<q.length;i++)ctx.lineTo(q[i].x,q[i].y);ctx.closePath();ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='#11191a';ctx.lineWidth=1;ctx.stroke();
    let cabin=[[-w*.36,-len*.24],[w*.36,-len*.24],[w*.31,len*.26],[-w*.31,len*.26]].map(a=>rot(a[0],a[1])).map(v=>proj(v[0],1.45,v[1]));
    if(cabin.every(Boolean)){ctx.beginPath();ctx.moveTo(cabin[0].x,cabin[0].y);cabin.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.closePath();ctx.fillStyle='#182627';ctx.fill();ctx.strokeStyle='#b9b29a55';ctx.stroke();}
    for(const side of [-1,1])for(const end of [-1,1]){
      const p=rot(side*w*.45,end*len*.38),q=proj(p[0],.75,p[1]);if(q){ctx.fillStyle=end===1?'#e6d49c':'#a04c3d';ctx.fillRect(q.x-2,q.y-1,4,2);}
    }
    if(hero){const sh=proj(x,2,z);if(sh){ctx.fillStyle='#e7d19b';ctx.font='9px monospace';ctx.fillText('YOUR RIDE',sh.x-25,sh.y-17);}}
  }
  function drawPerson(x,z,yaw,color,hero){
